337	
338	function isRecord(value: unknown): value is Record<string, unknown> {
339	  return typeof value === "object" && value !== null && !Array.isArray(value);
340	}
341	
342	function isNumericString(value: unknown): value is string {
343	  return typeof value === "string" && value.trim() !== "" && !Number.isNaN(Number(value));
344	}
345	
346	function coercePropertyMap(properties: Record<string, unknown>): Record<string, unknown> {
347	  return Object.fromEntries(
348	    Object.entries(properties).map(([propName, propValue]) => [
349	      propName,
350	      isNumericString(propValue) ? Number(propValue) : coerceNumericProperties(propValue),
351	    ]),
352	  );
353	}
354	
355	function coerceNumericProperties(obj: unknown): unknown {
356	  if (obj === null || obj === undefined) return obj;
357	  if (Array.isArray(obj)) return obj.map(coerceNumericProperties);
358	  if (!isRecord(obj)) return obj;
359	
360	  return Object.fromEntries(
361	    Object.entries(obj).map(([key, value]) => [
362	      key,
363	      key === "properties" && isRecord(value) ? coercePropertyMap(value) : coerceNumericProperties(value),
364	    ]),
365	  );
366	}
