368	class NotionMCPClient {
369	  state: MCPClientState = {
370	    connected: false,
371	    authenticated: false,
372	    sessionId: null,
373	    accessToken: null,
374	    mcpUrl: null,
375	  };
376	
377	  private messageId = 0;
378	  private sessionId: string | null = null;
379	  private _accessToken: string | null = null;
380	  private _tools: MCPTool[] = [];
381	
382	  async connect(mcpUrl: string, accessToken: string): Promise<void> {
383	    this._accessToken = accessToken;
384	    this.state.accessToken = accessToken;
385	    this.state.mcpUrl = mcpUrl;
386	    this.state.authenticated = true;
387	
388	    // Initialize MCP connection (session ID captured from response header in sendRequest)
389	    await this.sendRequest(mcpUrl, "initialize", {
390	      protocolVersion: "2024-11-05",
391	      capabilities: {},
392	      clientInfo: { name: "pi-notion", version: "1.0.0" },
393	    });
394	
395	    // If server didn't return a session ID, generate one locally
396	    if (!this.sessionId) {
397	      this.sessionId = randomBytes(16).toString("hex");
398	      this.state.sessionId = this.sessionId;
399	    }
400	    this.state.connected = true;
401	
402	    // Discover tools
403	    await this.discoverTools(mcpUrl);
404	
405	    // Send initialized notification
406	    await this.sendNotification(mcpUrl, "initialized", {});
407	  }
408	
409	  async disconnect(): Promise<void> {
410	    if (this.sessionId && this.state.mcpUrl) {
411	      try {
412	        await fetch(`${this.state.mcpUrl}/${this.sessionId}`, {
413	          method: "DELETE",
414	          headers: {
415	            "Content-Type": "application/json",
416	            Authorization: this._accessToken ? `Bearer ${this._accessToken}` : "",
417	          },
418	        });
419	      } catch {
420	        // Ignore errors on disconnect
421	      }
422	    }
423	    this.state = {
424	      connected: false,
425	      authenticated: false,
426	      sessionId: null,
427	      accessToken: null,
428	      mcpUrl: null,
429	    };
430	    this.sessionId = null;
431	    this._accessToken = null;
432	    this._tools = [];
433	  }
434	
435	  private getHeaders(): Record<string, string> {
436	    const headers: Record<string, string> = {
437	      "Content-Type": "application/json",
438	      Accept: "application/json, text/event-stream",
439	    };
440	    if (this.sessionId) {
441	      headers["MCP-Session-Id"] = this.sessionId;
442	    }
443	    if (this._accessToken) {
444	      headers.Authorization = `Bearer ${this._accessToken}`;
445	    }
446	    return headers;
447	  }
448	
449	  private async sendRequest(mcpUrl: string, method: string, params: Record<string, unknown>): Promise<unknown> {
450	    const id = ++this.messageId;
451	    const request = { jsonrpc: "2.0", id, method, params };
452	
453	    const response = await fetch(mcpUrl, {
454	      method: "POST",
455	      headers: this.getHeaders(),
456	      body: JSON.stringify(request),
457	    });
458	
459	    if (!response.ok) {
460	      const errorText = await response.text();
461	      throw new Error(`HTTP ${response.status}: ${errorText}`);
462	    }
463	
464	    // Capture session ID from response headers
465	    const sessionHeader = response.headers.get("mcp-session-id");
466	    if (sessionHeader) {
467	      this.sessionId = sessionHeader;
468	      this.state.sessionId = sessionHeader;
469	    }
470	
471	    const contentType = response.headers.get("content-type") || "";
472	    const data: { result?: unknown; error?: { message: string } } = contentType.includes("text/event-stream")
473	      ? await this.parseSSEResponse(response)
474	      : await response.json();
475	
476	    if (data.error) {
477	      throw new Error(`MCP Error: ${data.error.message}`);
478	    }
479	    return data.result;
480	  }
481	
482	  private async parseSSEResponse(response: Response): Promise<{ result?: unknown; error?: { message: string } }> {
483	    const text = await response.text();
484	    const lines = text.split("\n");
485	    for (const line of lines) {
486	      if (line.startsWith("data: ")) {
487	        const jsonStr = line.slice(6).trim();
488	        if (jsonStr) {
489	          return JSON.parse(jsonStr);
490	        }
491	      }
492	    }
493	    throw new Error("No data found in SSE response");
494	  }
495	
496	  private async sendNotification(mcpUrl: string, method: string, params: Record<string, unknown>): Promise<void> {
497	    const notification = { jsonrpc: "2.0", method, params };
498	    await fetch(mcpUrl, {
499	      method: "POST",
500	      headers: this.getHeaders(),
501	      body: JSON.stringify(notification),
502	    });
503	  }
504	
505	  private async discoverTools(mcpUrl: string): Promise<void> {
506	    try {
507	      const result = await this.sendRequest(mcpUrl, "tools/list", {});
508	      const tools = (result as { tools?: MCPTool[] })?.tools || [];
509	      this._tools = tools.map((tool) => ({
510	        name: tool.name,
511	        description: tool.description || "",
512	        inputSchema: (tool.inputSchema as Record<string, unknown>) || {},
513	      }));
514	    } catch {
515	      this._tools = [];
516	    }
517	  }
518	
519	  async callTool(mcpUrl: string, name: string, args: Record<string, unknown>): Promise<string> {
520	    const coerced = coerceNumericProperties(args);
521	    const result = await this.sendRequest(mcpUrl, "tools/call", { name, arguments: coerced });
522	
523	    // Format result
524	    const content = (result as { content?: Array<{ type: string; text?: string }> })?.content;
525	    if (content && Array.isArray(content)) {
526	      return content.map((c) => (c.type === "text" ? c.text : JSON.stringify(c))).join("\n");
527	    }
528	    return JSON.stringify(result);
529	  }
530	
531	  getTools(): MCPTool[] {
532	    return this._tools;
533	  }
534	}
