561	function getLegacyAuthFilePath(): string {
562	  const configDir = join(getHomeDir(), ".pi", "agent", "extensions");
563	  return join(configDir, "notion-mcp.json");
564	}
565	
566	function getDefaultAuthFilePath(): string {
567	  const configuredPath = process.env[NOTION_MCP_AUTH_FILE_ENV];
568	  if (typeof configuredPath === "string" && configuredPath.trim().length > 0) {
569	    return resolveAuthFilePath(configuredPath);
570	  }
571	
572	  const legacyConfiguredPath = process.env[NOTION_MCP_AUTH_FILE_LEGACY_ENV];
573	  if (typeof legacyConfiguredPath === "string" && legacyConfiguredPath.trim().length > 0) {
574	    console.warn("[pi-notion] NOTION_MCP_AUTH is deprecated; use NOTION_MCP_AUTH_FILE.");
575	    return resolveAuthFilePath(legacyConfiguredPath);
576	  }
577	
578	  const agentDir = join(getHomeDir(), ".pi", "agent");
579	  const legacyDir = join(agentDir, "extensions");
580	  const nextPath = join(agentDir, "notion-mcp-auth.json");
581	  const legacyPaths = [join(legacyDir, "notion-mcp-auth.json"), getLegacyAuthFilePath()];
582	
583	  for (const legacyPath of legacyPaths) {
584	    if (!existsSync(nextPath) && existsSync(legacyPath)) {
585	      try {
586	        mkdirSync(agentDir, { recursive: true });
587	        renameSync(legacyPath, nextPath);
588	        console.warn(`[pi-notion] Migrated legacy MCP auth file from ${legacyPath} to ${nextPath}.`);
589	      } catch (error) {
590	        const message = error instanceof Error ? error.message : String(error);
591	        console.warn(`[pi-notion] Failed to migrate legacy MCP auth file ${legacyPath}: ${message}`);
592	      }
593	    }
594	  }
595	
596	  return nextPath;
597	}
