704	function createRegisteredToolExecutor(
705	  client: NotionMCPClient,
706	  mcpUrl: string,
707	  tool: MCPTool,
708	): (
709	  _toolCallId: string,
710	  params: unknown,
711	  _signal: AbortSignal,
712	  _onUpdate: unknown,
713	  _ctx: unknown,
714	) => Promise<ToolExecutionResult> {
715	  return async (_toolCallId, params) => {
716	    if (!client.state.connected) {
717	      return toolError(tool.name, "Not connected to Notion MCP. Run /notion to connect.", { tool: tool.name });
718	    }
719	
720	    try {
721	      const result = await client.callTool(mcpUrl, tool.name, params as Record<string, unknown>);
722	      return toolResult(tool.name, result || "", { tool: tool.name });
723	    } catch (error) {
724	      const message = error instanceof Error ? error.message : String(error);
