770	async function finalizeConnection(
771	  client: NotionMCPClient,
772	  registration: ClientRegistration | null,
773	  accessToken: string,
774	  registerMCPTools: () => void,
775	  notify: NotifyFn,
776	): Promise<void> {
777	  notify("Connecting to MCP server...");
778	  await client.connect(NOTION_MCP_URL, accessToken);
779	  await storage.save({
780	    mcpUrl: NOTION_MCP_URL,
781	    accessToken,
782	    clientId: registration?.client_id,
783	    clientSecret: registration?.client_secret,
784	  });
785	  registerMCPTools();
786	}
