284	      "Content-Type": "application/x-www-form-urlencoded",
285	    },
286	    body: new URLSearchParams(params).toString(),
287	  });
288	
289	  if (!response.ok) {
290	    const error = await response.text();
291	    throw new Error(`${failurePrefix}: ${response.status} - ${error}`);
292	  }
