882	const TOKEN_REFRESH_SKEW_MS = 5 * 60 * 1000;
883	
884	// Notion may rotate refresh tokens, so concurrent 401s must share one refresh instead of racing.
885	let refreshInFlight: Promise<StoredConfig> | null = null;
886	
887	function isNearExpiry(config: StoredConfig): boolean {
888	  return config.expiresAt !== undefined && config.expiresAt - TOKEN_REFRESH_SKEW_MS <= Date.now();
889	}
