891	function refreshSavedConfig(savedConfig: StoredConfig, notify: NotifyFn): Promise<StoredConfig> {
892	  const { refreshToken } = savedConfig;
893	  if (!refreshToken) return Promise.reject(new Error("No saved Notion MCP refresh token"));
894	
895	  refreshInFlight ??= (async () => {
896	    notify("Refreshing saved Notion MCP token...");
897	    const refreshed = await refreshAccessToken(refreshToken, savedConfig.clientId, savedConfig.clientSecret);
898	    const nextConfig: StoredConfig = {
899	      ...savedConfig,
900	      accessToken: refreshed.accessToken,
901	      refreshToken: refreshed.refreshToken,
902	      expiresAt: refreshed.expiresAt,
903	    };
904	    await storage.save(nextConfig);
905	    return nextConfig;
906	  })().finally(() => {
907	    refreshInFlight = null;
908	  });
909	  return refreshInFlight;
910	}
