912	async function connectWithSavedConfig(client: NotionMCPClient, notify: NotifyFn): Promise<boolean> {
913	  const savedConfig = await storage.load();
914	  if (!savedConfig) return false;
915	
916	  notify("Connecting to saved Notion MCP...");
917	  try {
918	    let config = savedConfig;
919	    let refreshed = false;
920	    if (config.refreshToken && isNearExpiry(config)) {
921	      config = await refreshSavedConfig(config, notify);
922	      refreshed = true;
923	    }
924	
925	    try {
926	      await client.connect(config.mcpUrl, config.accessToken);
927	    } catch (error) {
928	      if (refreshed || !config.refreshToken || !(error instanceof AuthenticationError)) throw error;
929	      config = await refreshSavedConfig(config, notify);
930	      await client.connect(config.mcpUrl, config.accessToken);
931	    }
932	    return true;
933	  } catch (error) {
934	    // Keep saved credentials: a transient failure should not force a new OAuth consent,
935	    // and a successful OAuth fallback overwrites them anyway.
936	    const message = error instanceof Error ? error.message : String(error);
937	    notify(`Connection failed: ${message}`, "error");
938	    return false;
939	  }
940	}
