942	async function performOAuthConnection(notify: NotifyFn): Promise<OAuthConnectionData> {
943	  const state = randomBytes(16).toString("hex");
944	  const callbackServer = await startOAuthCallbackServer(3000, state);
945	  const callbackUrl = buildOAuthCallbackUrl(callbackServer.port);
946	
947	  notify("Registering OAuth client...");
948	  const registration = await registerClient(callbackUrl);
949	  const { codeVerifier, codeChallenge } = createPkceChallenge();
950	  const authUrl = buildAuthorizationUrl(registration, callbackUrl, codeChallenge, state);
951	
952	  announceAuthorizationUrl(authUrl, notify);
953	  notify("Opening Notion authorization page...");
954	  await openBrowser(authUrl);
955	  notify("Waiting for authorization callback...");
956	
957	  const callbackResult = await callbackServer.result;
958	  const tokens = await resolveAccessToken(callbackResult, callbackUrl, codeVerifier, registration, notify);
959	  return { tokens, registration };
960	}
