966	async function performManualOAuthConnection(notify: NotifyFn, input: OAuthInputFn): Promise<OAuthConnectionData> {
967	  const state = randomBytes(16).toString("hex");
968	  const callbackUrl = buildOAuthCallbackUrl(3000);
969	
970	  notify("Registering OAuth client...");
971	  const registration = await registerClient(callbackUrl);
