973	  const authUrl = buildAuthorizationUrl(registration, callbackUrl, codeChallenge, state);
974	
975	  announceAuthorizationUrl(authUrl, notify);
976	  notify(
977	    "Open the saved Notion URL in a browser on any machine. After approving, the redirect page will fail to load; paste its full URL here (the raw code also works).",
978	  );
979	  const pasted = await input("Paste the Notion redirect URL or code", `${callbackUrl}?code=...&state=...`);
980	  const callbackResult = parseManualOAuthCallbackInput(pasted ?? "", state);
981	  const tokens = await resolveAccessToken(callbackResult, callbackUrl, codeVerifier, registration, notify);
