985	async function finalizeConnection(
986	  client: NotionMCPClient,
987	  registration: ClientRegistration | null,
988	  tokens: TokenResponse,
989	  registerMCPTools: () => void,
990	  notify: NotifyFn,
991	): Promise<void> {
992	  notify("Connecting to MCP server...");
993	  await client.connect(NOTION_MCP_URL, tokens.accessToken);
994	  await storage.save({
995	    mcpUrl: NOTION_MCP_URL,
996	    accessToken: tokens.accessToken,
997	    refreshToken: tokens.refreshToken,
998	    expiresAt: tokens.expiresAt,
999	    clientId: registration?.client_id,
1000	    clientSecret: registration?.client_secret,
1001	  });
1002	  registerMCPTools();
1003	}
