1005	async function ensureConnected(
1006	  client: NotionMCPClient,
1007	  registerMCPTools: () => void,
1008	  notify: NotifyFn,
1009	  manualInput?: OAuthInputFn,
1010	): Promise<{ reusedSavedConfig: boolean }> {
1011	  const connectedFromSavedConfig = await connectWithSavedConfig(client, notify);
1012	  if (connectedFromSavedConfig) {
1013	    registerMCPTools();
1014	    return { reusedSavedConfig: true };
1015	  }
1016	
1017	  const { tokens, registration } = manualInput
1018	    ? await performManualOAuthConnection(notify, manualInput)
1019	    : await performOAuthConnection(notify);
1020	  await finalizeConnection(client, registration, tokens, registerMCPTools, notify);
1021	  return { reusedSavedConfig: false };
1022	}
