      vi.spyOn(storage, "load").mockResolvedValue({
        mcpUrl: MCP_URL,
        accessToken: "still-valid",
        refreshToken: "refresh-1",
        expiresAt: Date.now() + 60_000,
        clientId: "client",
      });
      const clearSpy = vi.spyOn(storage, "clear").mockResolvedValue();
