/** Pings the server; a 401 marks the client disconnected so callers reconnect. */
async checkConnection(mcpUrl: string): Promise<boolean> {
  try {
    await this.sendRequest(mcpUrl, "tools/list", {});
    return true;
  } catch (error) {
